import{_ as i,o as e,c as l,a3 as t}from"./chunks/framework.CJlOecQn.js";const p=JSON.parse('{"title":"كيف نوثّق المعلومات","description":"القواعد التي يجب أن تمر بها كل معلومة في هذا الدليل.","frontmatter":{"title":"كيف نوثّق المعلومات","description":"القواعد التي يجب أن تمر بها كل معلومة في هذا الدليل."},"headers":[],"relativePath":"ar/sourcing.md","filePath":"ar/sourcing.md"}'),r={name:"ar/sourcing.md"};function o(n,a,s,c,h,d){return e(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="كيف-نوثّق-المعلومات" tabindex="-1">كيف نوثّق المعلومات <a class="header-anchor" href="#كيف-نوثّق-المعلومات" aria-label="Permalink to &quot;كيف نوثّق المعلومات&quot;">​</a></h1><p>لهذا الدليل قاعدة واحدة: إذا لم نجد صفحة رسمية تثبت المعلومة، فلا مكان لها فيه.</p><h2 id="ما-الذي-نعدّه-مصدرًا-رسميًا" tabindex="-1">ما الذي نعدّه مصدرًا رسميًا <a class="header-anchor" href="#ما-الذي-نعدّه-مصدرًا-رسميًا" aria-label="Permalink to &quot;ما الذي نعدّه مصدرًا رسميًا&quot;">​</a></h2><ul><li>المواقع الحكومية في دولة قطر: بوابة حكومي والوزارات والمجالس والهيئات على النطاق gov.qa، مثل وزارة الداخلية ووزارة العمل ووزارة الصحة العامة ومصرف قطر المركزي.</li><li>نصوص القوانين الرسمية على بوابة الميزان القانونية.</li><li>الجهات العامة والشركات المملوكة للدولة فيما يخص خدماتها: مؤسسة حمد الطبية وكهرماء ومواصلات (كروة) والريل ومطار حمد الدولي والبريد القطري وزوروا قطر.</li><li>اللجنة الوطنية لحقوق الإنسان، ويدعم كتيب العمال الصادر عنها صفحة العمل.</li><li>مشغلو الاتصالات المرخّصون، فيما يخص خدماتهم فقط.</li></ul><p>القائمة الكاملة في الملف <a href="https://github.com/Ifazawezk/living-in-qatar/blob/main/scripts/official_domains.txt" target="_blank" rel="noreferrer"><code>scripts/official_domains.txt</code></a>. لا نعتمد أبدًا على الأخبار أو المنتديات أو المدونات أو شركات الانتقال أو منشورات وسائل التواصل، حتى لو تبيّن أنها صحيحة. قد تفيد في معرفة ما يجب البحث عنه، لا أكثر.</p><h2 id="كيف-تدخل-المعلومة-إلى-الدليل" tabindex="-1">كيف تدخل المعلومة إلى الدليل <a class="header-anchor" href="#كيف-تدخل-المعلومة-إلى-الدليل" aria-label="Permalink to &quot;كيف تدخل المعلومة إلى الدليل&quot;">​</a></h2><ol><li>تُفتح الصفحة الرسمية وتُقرأ.</li><li>تُكتب المعلومة بلغة بسيطة، مع حاشية فيها رابط الصفحة بعينها والشهر الذي جرى التحقق فيه منها.</li><li>تستشهد الصفحة العربية بالحواشي نفسها، ويفشل الفحص الآلي إذا اختلفت مصادر اللغتين.</li><li>عند تقديم طلب الدمج، يتأكد سكربت من أن لكل فقرة وكل بند في قائمة وكل صف في جدول مصدرًا رسميًا، ويفتح المراجع كل رابط جديد بنفسه.</li></ol><h2 id="الرسوم-والأرقام" tabindex="-1">الرسوم والأرقام <a class="header-anchor" href="#الرسوم-والأرقام" aria-label="Permalink to &quot;الرسوم والأرقام&quot;">​</a></h2><p>الرسوم أكثر ما يتغير، لذلك نفضّل غالبًا الربط بصفحة الرسوم أو الخدمة الرسمية بدل نسخ المبلغ. وحين يظهر رقم في الدليل، مثل رقم طوارئ أو عدد أيام إجازة، فهو مكتوب في الصفحة المرتبطة به.</p><h2 id="كيف-نُبقي-الدليل-محدّثًا" tabindex="-1">كيف نُبقي الدليل محدّثًا <a class="header-anchor" href="#كيف-نُبقي-الدليل-محدّثًا" aria-label="Permalink to &quot;كيف نُبقي الدليل محدّثًا&quot;">​</a></h2><ul><li>في نهاية كل حاشية عبارة &quot;آخر تحقق&quot; مع الشهر.</li><li>الأمر <code>python scripts/check_links.py</code> يزور كل روابط المصادر، ويبلّغ عن الروابط المعطلة، والروابط التي صارت تحوّل إلى مكان آخر، والصفحات التي تغيّر عنوانها منذ آخر تشغيل محفوظ.</li><li>بعض المواقع الحكومية تحجب الزوار الآليين، فيضعها الفحص في قائمة مستقلة باسم &quot;محجوب&quot; ليفتحها شخص في المتصفح ويتأكد منها بنفسه.</li><li>الأمر <code>python scripts/lint_content.py --stale-after 12</code> ينبّه إلى المصادر التي لم يتحقق منها أحد منذ سنة.</li></ul><h2 id="ما-الذي-نتركه" tabindex="-1">ما الذي نتركه <a class="header-anchor" href="#ما-الذي-نتركه" aria-label="Permalink to &quot;ما الذي نتركه&quot;">​</a></h2><ul><li>كل ما لم نستطع تأكيده من صفحة رسمية. هذه البنود تذهب إلى قائمة <a href="./help-wanted">نحتاج مساعدتك</a>.</li><li>أسعار الإيجارات والبقالة، وترتيب المدارس أو الأحياء، والآراء في أصحاب العمل. لا يوجد مصدر رسمي لها، وتتقادم بسرعة.</li></ul><h2 id="ليس-استشارة-قانونية" tabindex="-1">ليس استشارة قانونية <a class="header-anchor" href="#ليس-استشارة-قانونية" aria-label="Permalink to &quot;ليس استشارة قانونية&quot;">​</a></h2><p>هذا مشروع مجتمعي، لا تديره أي جهة حكومية ولا يرتبط بها. يشرح أين تبحث وماذا تقول الصفحات الرسمية بلغة بسيطة. وفي أي قرار مهم اقرأ الصفحة الرسمية، وإذا كانت حالتك غير معتادة فاسأل الجهة المختصة مباشرة.</p>',15)])])}const _=i(r,[["render",o]]);export{p as __pageData,_ as default};
